// Ambient speech-bubble lines for anonymous city folk (Maple Bay).
// Structure and categories: docs/reports/city_lines.md (the lead's plan). Engine: src/sim/_crowd_lines.js.
// Every pool is a shuffle bag: no line repeats until its whole pool has fired. No line here repeats
// another line in this file or in AMBIENT (src/story/dialogue.js).
//
//   general.<theme>        the big pool, anywhere, any time (22 themes; the engine flattens them into
//                          one bag). May use {district}.
//   district.<key>         downtown, oldtown, harbor, hillcrest, maplewood, arts, railyard, park, airport
//   near.<landmark>        within a block of a landmark (fountain, pier, lighthouse, ... crosswalk)
//   venue.<room>           overheard indoors (cafe, bakery, ... restroom_queue)
//   timeOfDay.<slot>       dawn, morning, midday, afternoon, evening, late, night
//   weekday.<day>          monday ... sunday
//   season.<id>            spring, summer, autumn, winter
//   weather.<kind>         sunny, cloudy, rain, storm, fog, snow, heat, wind, first_snow, rainbow
//   events.<calendar id>   while the event is on or the day before (+ rent_day, payday, new_year,
//                          star_party, flower_show)
//   kind.<activity>        what the speaker is doing (jogger, carrier, queue, ... late_runner)
//   duets                  [lineA, lineB] pairs for two people standing together: A, then B a beat later
//   duets_by.venue.<room> / duets_by.kind.couple / duets_by.kind.kid   same shape, keyed
//   player.<state>         said ABOUT or TO the player by someone a few steps away, because of what a
//                          passer-by can see. Witty, never cruel: the town is kind. {name} only in
//                          player.regular and player.birthday.
//
// Running gags shared across pools: the City Hall fountain that will be fixed "soon", Gerald the
// one-footed pigeon, the 14 bus never being on time, a sourdough starter called Brenda, Wick the
// lighthouse keeper's cat, the Ferris wheel that always stops at the top, the mysterious Finch of
// Hartwell & Finch, the Maître G (the Gilded Gull's gull), the lighthouse blinking twice on Fridays,
// Streetcar No. 9, and Mercy (the bench halfway up the Hillcrest stairs).
//
// Rules: plain strings, <= 90 chars, one bubble each, no tokens except {name} / {district}.

