      "I posted a photo of my lunch on Circle. My mom commented 'nice soup'. It's a curry.",
      "I updated the Wander app and now everything's a different color. I'm lost.",
      "I've got so many apps I need an app to find my apps.",
      "My dad sent me a voice note. It was eleven minutes of him trying to send a voice note.",
      "Phone's in my pocket. Phone's in my bag. Phone's in my hand. Panic over.",
