      "I've been typing for ten minutes and it's a reply to 'ok'.",
      "Battery's dying. Tell the group chat I loved them.",
      "Bought new earbuds. Lost one in a day. Now I listen in mono, like a pirate.",
      "I posted the sunset on Circle. Forty likes. The sun did all the work.",
      "MapleCab driver gave me a five-star chat about his tomatoes.",
      "The new phone does everything. I use it for the flashlight.",
      "My partner and I text each other from different rooms. Modern romance.",
      "I've got two phones. One for work, one for pictures of dogs.",
      "The Appy store wanted me to rate the Appy store. Inception.",
      "My kid fixed the TV in ten seconds and called me 'old'. Fair.",
