      "Hiccups for an hour. Tried everything. A gull scared them out of me.",
      "I've started taking vitamins. I feel exactly the same, but righteous.",
      "Nap at two, nap at four. Doctor's orders. The doctor is me.",
      "Morning stretch, evening stretch, crossword stretch. My brain does yoga.",
      "I've got a cough that sounds like the foghorn. Very local cough.",
      "Drank a green smoothie. Tasted like a lawn. Feel fantastic, though.",
      "Ran for the bus, didn't make it, still counts as cardio.",
      "My dentist says I grind my teeth. It's the 14 bus. It's stress.",
      "My sleep app says I slept 'restlessly'. I dreamed about soup.",
      "Iron Maple Gym has a class called 'Gentle Burn'. It's not gentle. It burns.",
      "I'm on day three of no coffee. I'm also on day three of crying at adverts.",
      "Rested my legs on Mercy for so long I took root.",
      "I went to the Bayside Clinic for a sniffle. Left with a lollipop. Cured.",
