      "Took a long bath with a book. Came out wrinkled and wise.",
      "I've been doing squats every time I brush my teeth. Strong legs, clean teeth.",
      "My doctor told me to reduce stress. I laughed. She laughed. Then she sighed.",
      "I'm walking off lunch. Lunch is winning.",
      "Getting older means my back does the weather forecast now.",
      "My knees predicted this. My knees are never wrong.",
      "My dentist says I have nice teeth. First compliment all month.",
      "My doctor told me to walk more. So here I am. Walking. Look at me.",
      "The gym's offering a free class. I'm going to go and watch.",
      "I'm so tired of my own cooking. Somebody adopt me for dinner.",
      "I've got a dentist appointment. I've been flossing all morning. Too late?",
      "I've got a list of things to do and a nap scheduled after each.",
      "I'm going to the library to work. And to nap near books.",
      "Ten hours on the dock. Tonight I sleep like an anchor.",
      "If I don't get a nap I'm going to become a different person. A worse one.",
