      "I'm learning the cello. My neighbors are learning patience.",
      "My plants are thriving. I've no idea what I'm doing right.",
      "Who keeps putting tiny knitted hats on the bollards? I love them.",
      "Somebody painted a tiny door on the base of that tree. For the mice, I hope.",
      "I joined a book club. We don't read the books. We love the snacks.",
      "I give my plants pep talks. The fern listens. The cactus doesn't.",
      "Somebody on our floor is learning the trumpet. One note at a time.",
      "If anyone asks, I'm not hiding from my book club.",
