      "I told my plants I'd be back by six. I'm a liar.",
      "I've been trying to whistle for forty years. Today I whistled. Nobody saw.",
      "I'm doing a crossword in pen. That's who I am now.",
      "Did you know the river freezes some winters? People skate on it. Gently.",
      "I took a wrong turn and found a garden I didn't know existed. Best wrong turn.",
      "There's a guy painting the bridge railings by hand. One by one. Legend.",
      "My neighbor waters her plants in a bathrobe every morning. A real institution.",
      "I want to learn to sail. I also get seasick in the bath.",
      "Somebody painted the fire hydrant like a ladybug. I support this.",
      "Every spring my neighbor buys a new garden gnome. There are forty now.",
      "I tried roller skating on the boardwalk. The boardwalk won.",
      "I painted the light on the river for three hours. It moved. Rude.",
      "My gallery show opens Friday. I've changed one painting seven times.",
      "I'm a sculptor. Mostly I sculpt excuses for my landlord.",
      "Somebody's piano lesson is drifting out of a window. Scales. Up. Down. Up.",
      "A man just tipped his hat to me. An actual hat. I felt like a duchess.",
      "I bought a houseplant called a 'Lucky Bamboo'. So far: average luck.",
      "Just found out my neighbor is a magician. Explains the rabbits.",
      "My friend got a tattoo of the lighthouse. Then the lighthouse got repainted.",
      "Look at that light on the water. Somebody should paint that. Somebody always is.",
      "We're putting on a puppet show at the school. I'm the moon. Big role.",
      "Somebody in {district} keeps planting sunflowers in odd places. Hero.",
