      "I'm going to the mall. I'm going to buy one thing. I'm a liar.",
      "We're going to the Symphony Hall tonight. I'm wearing my good socks.",
      "I'm going to tidy my apartment this weekend. And by tidy I mean move things around.",
      "I'm going to the hardware store for one screw. I'll come back with a shed.",
