      "The pier planks bounce a bit. Like the pier's happy to see you.",
      "A man's been fishing at the end of the pier since dawn. One sock caught so far.",
      "The arcade at the end of the pier still has the claw machine nobody's beaten.",
      "Hot doughnuts on the pier! Cinnamon sugar everywhere! On everyone!",
      "I watch the sun go down from the pier every night. It hasn't missed a show yet.",
      "Somebody proposed at the end of the pier last week. The gulls applauded. Probably.",
